const crypto = require('crypto');

// Example passwords array
const passwords = ['password1', 'password2', 'password3'];

console.time('Synchronous hashing');
for (let i = 0; i < passwords.length; i++) {
    const salt = crypto.randomBytes(32);
    const hashedPassword = crypto.pbkdf2Sync(passwords[i], salt, 10000, 32, 'sha256');
}
console.timeEnd('Synchronous hashing');

// Example measuring async performance (for comparison)
const asyncHashPasswords = async (passwords) => {
    return Promise.all(passwords.map(async (password) => {
        const salt = crypto.randomBytes(32);
        return new Promise((resolve) => {
            crypto.pbkdf2(password, salt, 10000, 32, 'sha256', (err, hashedPassword) => {
                resolve([hashedPassword, salt]);
            });
        });
    }));
};

console.time('Asynchronous hashing');
asyncHashPasswords(['password1', 'password2', 'password3']).then(() => {
    console.timeEnd('Asynchronous hashing');
});

